WITH cat AS (
    SELECT code, id
    FROM sys_category
    WHERE app_code = 'jia'
      AND type = 'food_main'
),
classified AS (
    SELECT
        f.id,
        CASE
            WHEN f.name ~ '(黄酒|白酒|葡萄酒|啤酒|香槟|大曲|二曲|老窖|曲酒|烧酒|二锅头|佳酿)'
                THEN 'food_main_alcohol'
            WHEN f.name ~ '(茶水|茶汤|茶叶|红茶|绿茶|花茶|龙井|铁观音|珠茶|砖茶|咖啡|果汁|饮料|汽水|可乐|苏打|酸梅汤|甘蔗汁|刺玫汁|神力宝|豆汁)'
                THEN 'food_main_beverage'
            WHEN f.name ~ '(酱$|^酱|酱\(|酱）|酱\)|酱油|醋|糖$|盐$|味精|胡椒|花椒|大料|八角|桂皮|咖喱|芥末|腐乳|豆豉|陈皮|丁香|甘草|茴香|薄荷|藿香|白芷|蜂蜜|肉桂|肉豆蔻|可可粉)'
                THEN 'food_main_condiment'
            WHEN f.name ~ '(油$|白脱|奶油|黄油|牛油|猪油|羊油|鸡油|鸭油|麻油|香油|混合油)'
                THEN 'food_main_oil'
            WHEN f.name ~ '(蛋|皮蛋|松花蛋)'
                THEN 'food_main_egg'
            WHEN f.name ~ '(牛奶|羊奶|奶粉|酸奶|奶酪|干酪|炼乳|冰淇淋|冰砖|冰棍|雪糕|奶片|奶皮子|奶疙瘩|奶酷干|果味奶)'
                THEN 'food_main_milk'
            WHEN f.name ~ '(豆腐|豆浆|豆皮|豆干|腐竹|豆粕|豆沙|豆奶|黄豆|黑豆|绿豆|赤豆|红小豆|红豆|芸豆|豌豆|蚕豆|扁豆|刀豆|发芽豆|花豆|苦豆子|毛豆|青豆|百页|千张|卤干|烤麸)'
                THEN 'food_main_bean'
            WHEN f.name ~ '(稻米|稻谷|谷子|龙谷|大黄米|黄米|小米|江米|糯米|大米|黑米|粳米|籼米|小麦|大麦|燕麦|荞麦|高粱|玉米|青稞|稞麦|糜子|标准粉|富强粉|精粉|挂面|面条|面包|米饭|米线|米粉|馒头|烙饼|烧麦|面窝|麸皮)'
                THEN 'food_main_cereal'
            WHEN f.name ~ '(薯|芋|山药|藕粉|土豆|马铃薯|红薯|木薯|淀粉|粉皮|粉条|粉丝|凉粉|芡粉|慈蛄|荸荠|酿皮子)'
                THEN 'food_main_tuber'
            WHEN f.name ~ '(花生|芝麻|核桃|榛子|杏仁|腰果|松子|瓜子|栗|板粟|白果|莲子|胡麻|麻子|木榧)'
                THEN 'food_main_nut_seed'
            WHEN f.name ~ '(菇|菌|蘑|木耳|银耳|香蕈|地衣|茯苓|昆布|海带|紫菜|发菜|松茸|龙须菜|琼脂|淡菜)'
                THEN 'food_main_fungi_algae'
            WHEN f.name ~ '(苹果|梨|桃|李|杏|梅|枣|橙|柑|橘|桔|柚|柠檬|葡萄|樱桃|草莓|菠萝|香蕉|芭蕉|板蕉|甘蕉|荔枝|龙眼|桂圆|芒果|西瓜|甜瓜|哈密瓜|椰子|桑葚|榴莲|山楂|山里红|番石榴|金桔|黄皮|橄榄|枇杷|石榴|柿|沙棘|红果|果脯|蜜饯|果丹皮|海棠脯|离枝|楸子|棘)'
                THEN 'food_main_fruit'
            WHEN f.name ~ '(白菜|菠菜|芹|韭|香菜|茼蒿|茄|瓜|萝卜|番茄|西红柿|番柿|辣椒|椒$|黄瓜|冬瓜|南瓜|苦瓜|丝瓜|洋葱|蒜|姜|葱|笋|藕|苋|莴苣|芥|蕨|百合|葫芦|荷兰豆|豇豆|豆角|大豆角|茭白|黄秋葵|秋葵|旱芹|红菜苔|球茎甘蓝|苤蓝|苦菜|生菜|莼菜|艾菜|马兰|苜蓿|菜$|^菜)'
                THEN 'food_main_vegetable'
            WHEN f.name ~ '(甲鱼|比目鱼|鲒花|白斑角鲨|海河乌江|海蛎|乌贼|枪乌贼|墨鱼|章鱼|鱼|虾|蟹|贝|蛤|螺|蚬|蚝|牡蛎|海参|海蜇|鱿|鳗|鳕|鲫|鲤|鲢|鲳|鲈|鳊|鳝|泥鳅|蛏|蚌|蚶|干贝|扇贝|鳖|龟|鲨|鲩|鲷|鲂|鲇|鲶|鳟|鲭|鲐|鲻|鲮|鲴|鲍|鲎|鲆|沙梭|曼氏无针乌贼)'
                THEN 'food_main_aquatic'
            WHEN f.name ~ '(鸡|鸭|鹅|鸽|鹌鹑|鹧鸪|斑鸠|麒麟鸟|老鸦)'
                THEN 'food_main_poultry'
            WHEN f.name ~ '(猪|牛|羊|驴|兔|狗肉|马肉|驼|叉烧|方腿|酱汁肉|火腿|腊肉|香肠|肘|排骨|肝|肚|肠|腰|心|肺|蹄|耳|舌|血|肥肠|老鼠肉|蛇|青蛙|青蛙腿|软五花)'
                THEN 'food_main_livestock'
            WHEN f.name ~ '(酥|卷$|春卷|艾窝窝|焦圈|京八件|糕|饼干|麻花|点心|江米条|麻团|巧克力|开口笑|三刀蜜|汤包|胖子|两公婆|德庆酥|凤尾酥|福来酥|黑麻香酥|黑洋酥|金钱酥|佛手疙瘩)'
                THEN 'food_main_snack'
            WHEN f.name ~ '(罐头|方便面|午餐肉|火腿肠|虾条|麦乳精|宝宝福|冲剂|健儿粉|全料蒸肉粉|素什锦)'
                THEN 'food_main_convenience'
            ELSE 'food_main_other'
        END AS target_code
    FROM jia_food f
)
UPDATE jia_food AS f
SET category_id = c2.id
FROM classified AS cls
JOIN cat AS c2 ON c2.code = cls.target_code
WHERE f.id = cls.id;

COMMIT;
